import * as THREE from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { mix, vUV, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Design tokens
  const colors = {
    paper: new THREE.Color(0xe8ecf2),
    accent: new THREE.Color(0xff2a38),
    gradStart: new THREE.Color(0x121218),
    gradEnd: new THREE.Color(0x0b0b10),
    hairline: new THREE.Color(0x23232b)
  };

  const footerWidth = 6.8;
  const footerHeight = 2.0;

  // Surface material: vertical gradient + PBR
  const surfaceMat = new MeshStandardNodeMaterial({
    colorNode: mix(
      uniform(colors.gradStart),
      uniform(colors.gradEnd),
      vUV.y
    ),
    roughnessNode: uniform(0.6),
    metalnessNode: uniform(0.2),
    side: THREE.DoubleSide
  });

  // Hairline/emissive material
  const hairlineMat = new MeshStandardNodeMaterial({
    colorNode: uniform(colors.hairline),
    emissiveNode: uniform(colors.hairline),
    emissiveIntensityNode: uniform(1.4),
    roughnessNode: uniform(0.6),
    metalnessNode: uniform(0.2),
    side: THREE.DoubleSide
  });

  // Main surface plane
  const planeGeom = new THREE.PlaneGeometry(footerWidth, footerHeight);
  const plane = new THREE.Mesh(planeGeom, surfaceMat);
  plane.position.z = -0.01;
  plane.castShadow = false;
  plane.receiveShadow = true;
  group.add(plane);

  // Top hairline (etched edge)
  const hairlineTopGeom = new THREE.PlaneGeometry(footerWidth, 0.006);
  const hairlineTop = new THREE.Mesh(hairlineTopGeom, hairlineMat);
  hairlineTop.position.set(0, footerHeight / 2 - 0.003, 0.002);
  group.add(hairlineTop);

  // Helper to create text via fontAtlas
  const createTextElement = (text, style) => {
    return ctx.fontAtlas.createText(text, style);
  };

  // Wordmark (left block)
  const wordmarkText = createTextElement('NOVA ATELIER', {
    font: 'Lora',
    fontSize: 34,
    fontWeight: 600,
    color: colors.paper,
    letterSpacing: 0.02
  });
  wordmarkText.position.set(-2.8, 0.48, 0.01);
  wordmarkText.scale.multiplyScalar(0.015);
  group.add(wordmarkText);

  // Accent bar (below wordmark)
  const accentBarGeom = new THREE.PlaneGeometry(0.3, 0.02);
  const accentMat = new MeshStandardNodeMaterial({
    colorNode: uniform(colors.accent),
    emissiveNode: uniform(colors.accent),
    emissiveIntensityNode: uniform(1.4),
    roughnessNode: uniform(0.8),
    metalnessNode: uniform(0.1)
  });
  const accentBar = new THREE.Mesh(accentBarGeom, accentMat);
  accentBar.position.set(-2.8, 0.16, 0.01);
  group.add(accentBar);

  // Link state tracking for hover
  const linkStates = [];

  // Three link columns
  const columns = [
    { header: 'ATELIER', x: -0.9, links: ['Features', 'Collection', 'Pricing'] },
    { header: 'COMPANY', x: 0.6, links: ['Journal', 'Visit the Atelier', 'Contact'] },
    { header: 'LEGAL', x: 2.1, links: ['Privacy', 'Terms', 'Warranty'] }
  ];

  columns.forEach(col => {
    // Column header
    const headerText = createTextElement(col.header, {
      font: 'JetBrains Mono',
      fontSize: 9,
      fontWeight: 700,
      color: colors.paper,
      letterSpacing: 0.12
    });
    headerText.position.set(col.x, 0.58, 0.01);
    headerText.scale.multiplyScalar(0.012);
    group.add(headerText);

    // Links (1.8 line height = ~0.23 scene units)
    col.links.forEach((linkText, idx) => {
      const linkMesh = createTextElement(linkText, {
        font: 'JetBrains Mono',
        fontSize: 13,
        fontWeight: 400,
        color: colors.paper,
        letterSpacing: 0
      });
      const yPos = 0.32 - idx * 0.23;
      linkMesh.position.set(col.x, yPos, 0.01);
      linkMesh.scale.multiplyScalar(0.013);
      group.add(linkMesh);

      linkStates.push({
        mesh: linkMesh,
        isHovered: false
      });
    });
  });

  // Legal text line
  const legalText = createTextElement(
    '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.',
    {
      font: 'JetBrains Mono',
      fontSize: 9,
      fontWeight: 400,
      color: colors.paper,
      letterSpacing: 0.04
    }
  );
  legalText.position.set(-3.2, -0.82, 0.01);
  legalText.scale.multiplyScalar(0.011);
  group.add(legalText);

  // Bottom hairline (above legal text)
  const hairlineBottomGeom = new THREE.PlaneGeometry(footerWidth, 0.006);
  const hairlineBottom = new THREE.Mesh(hairlineBottomGeom, hairlineMat);
  hairlineBottom.position.set(0, -0.7, 0.002);
  group.add(hairlineBottom);

  // Hover handlers for links
  group.userData.handlers = {
    onPointerMove: (raycaster, mouse) => {
      if (!raycaster) return;

      const intersects = raycaster.intersectObjects(
        linkStates.map(s => s.mesh),
        true
      );
      const hoveredSet = new Set(intersects.map(h => h.object));

      linkStates.forEach(state => {
        const isHovered = hoveredSet.has(state.mesh);

        if (isHovered && !state.isHovered) {
          state.isHovered = true;
          // Hover in: color to accent + translateZ
          gsap.to(state.mesh.material, {
            color: colors.accent,
            duration: 0.14,
            ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
          });
          gsap.to(state.mesh.position, {
            z: 0.03,
            duration: 0.14,
            ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
          }, 0);
        } else if (!isHovered && state.isHovered) {
          state.isHovered = false;
          // Hover out: color back to paper
          gsap.to(state.mesh.material, {
            color: colors.paper,
            duration: 0.14,
            ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
          });
          gsap.to(state.mesh.position, {
            z: 0.01,
            duration: 0.14,
            ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
          }, 0);
        }
      });
    }
  };

  // Mount animation: fade-up (opacity 0→1, y +0.2→0)
  const animState = { opacity: 0 };
  group.position.y = 0.2;

  // Set initial transparency
  group.traverse(obj => {
    if (obj.material) {
      obj.material.transparent = true;
      obj.material.opacity = 0;
    }
  });

  // Animate opacity via onUpdate
  gsap.to(animState, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
    onUpdate() {
      group.traverse(obj => {
        if (obj.material) {
          obj.material.opacity = animState.opacity;
        }
      });
    }
  });

  // Animate position
  gsap.to(group.position, {
    y: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
  }, 0);

  // Cleanup
  group.userData.cleanup = () => {
    gsap.killTweensOf(animState);
    gsap.killTweensOf(group.position);
    linkStates.forEach(s => {
      gsap.killTweensOf(s.mesh.material);
      gsap.killTweensOf(s.mesh.position);
    });

    group.traverse(obj => {
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach(m => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
      if (obj.geometry) obj.geometry.dispose();
    });
  };

  return group;
}
